pub(crate) const STYLES: &str = r#"
.df-combat{--gold:#dfb974;--muted:#b6bec6;position:relative;isolation:isolate;min-height:100svh;background:#070d14;color:#f5eee0;font:16px/1.5 Georgia,'Times New Roman',serif;overflow:hidden}
.df-combat *{box-sizing:border-box;min-width:0}.df-combat [hidden]{display:none!important}.df-combat p,.df-combat h1,.df-combat h2,.df-combat h3,.df-combat button,.df-combat dd{overflow-wrap:anywhere}.df-combat .combat-art{position:absolute;inset:0;width:100%;height:800px;object-fit:cover;object-position:center 35%;z-index:-3;color:#b6bec6}.df-combat:before{content:'';position:absolute;inset:0;z-index:-2;background:linear-gradient(180deg,#03080f8a,transparent 20%,#03080f30 37%,#070d14 780px),linear-gradient(90deg,#03080f50,transparent 65%)}
.df-combat .combat-topbar{display:flex;align-items:center;gap:24px;padding:23px 4vw;border-bottom:1px solid #dcb87c33;background:#08111b55}.df-combat .combat-brand{font-size:29px;letter-spacing:-1px;color:#f3d59d}.df-combat .combat-location{flex:1;margin:0;font:11px/1.6 system-ui,sans-serif;text-transform:uppercase;letter-spacing:2px;color:#ccd9df}.df-combat .combat-notice{font:10px/1.5 system-ui,sans-serif;letter-spacing:1px;border:1px solid #bda16866;padding:9px 13px;color:#e5c992;background:#08111bc9;border-radius:3px}
.df-combat .combat-stage{width:min(1480px,92vw);margin:auto;display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:6vw;align-items:end;min-height:535px;padding:85px 0 38px}.df-combat .combat-story{padding-bottom:20px}.df-combat .combat-overline{font:11px/1.7 system-ui,sans-serif;letter-spacing:2.5px;text-transform:uppercase;color:var(--gold);margin:0 0 18px}.df-combat h1{font-weight:400;font-size:clamp(45px,5.8vw,86px);line-height:1.04;letter-spacing:-2px;text-shadow:0 3px 35px #000;margin:0 0 24px;max-width:820px}.df-combat .combat-narration{font-size:19px;line-height:1.7;color:#e4e1d8;max-width:630px;margin:0;text-shadow:0 2px 8px #000}
.df-combat .combat-initiative{padding:22px;background:linear-gradient(150deg,#111c29ee,#08101cef);border:1px solid #b39a6366;border-radius:4px;box-shadow:0 20px 60px #0006}.df-combat .combat-actors,.df-combat .combat-rolls{list-style:none;margin:0;padding:0}.df-combat .combat-actor{display:flex;gap:14px;align-items:start;padding:14px 0;border-top:1px solid #b2bcc528}.df-combat .combat-actor[data-active=true]{border-left:2px solid #efc471;padding-left:13px;background:linear-gradient(90deg,#a4792b22,transparent)}.df-combat .combat-initiative-value{width:36px;min-width:36px;height:38px;display:grid;place-items:center;background:#142432;border:1px solid #aabcce33;border-radius:3px;color:#c8d7df;font:18px/1 Georgia,serif}.df-combat .combat-actor[data-active=true] .combat-initiative-value{color:#f0d18f;border-color:#bea064}.df-combat h3{font-weight:400;margin:0;font-size:18px;line-height:1.4}.df-combat .combat-muted{font:12px/1.6 system-ui,sans-serif;color:var(--muted);margin:6px 0 0}.df-combat .combat-resources{display:grid;grid-template-columns:auto 1fr;column-gap:12px;row-gap:3px;margin:8px 0 0;font:11px/1.6 system-ui,sans-serif}.df-combat .combat-resources dt{color:#95a9b9}.df-combat .combat-resources dd{margin:0;color:#e0d9c9;text-align:right}
.df-combat .combat-lower{width:min(1480px,92vw);margin:auto;display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,1fr);gap:24px;padding:0 0 32px}.df-combat .combat-action-rail,.df-combat .combat-roll-panel{padding:27px 30px;border:1px solid #ad925d55;background:linear-gradient(130deg,#111c29f5,#08101cf5);border-radius:4px;box-shadow:0 14px 40px #0003}.df-combat h2{font-weight:400;font-size:26px;line-height:1.3;margin:0 0 21px}.df-combat .combat-offers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.df-combat .combat-offer{border:1px solid #92a5b033;background:#08111b80;padding:12px;border-radius:3px}.df-combat .combat-offer[data-kind=roll]{border-color:#d4b07366;background:linear-gradient(130deg,#79552820,#08111b)}.df-combat .combat-offer[data-kind=reaction]{border-color:#71b7cd66}.df-combat button{width:100%;min-height:48px;border:1px solid #b49b6266;background:#1f2c3be0;color:#f0dfbc;border-radius:3px;padding:10px 15px;font:14px/1.5 system-ui,sans-serif;cursor:pointer;touch-action:manipulation}.df-combat button:hover:enabled{background:#4b3d28;border-color:#e5bd77}.df-combat button:disabled{color:#95a4b2;background:#111923;cursor:default;border-color:#92a5b02e}.df-combat :focus-visible{outline:3px solid #8dd4f3;outline-offset:4px}.df-combat button[aria-busy=true]{border-style:dashed}.df-combat .combat-offer p{margin:9px 0 0}
.df-combat .combat-reaction{margin-top:23px;padding:18px 20px;border:1px solid #74bacc66;border-left:3px solid #9ad4df;background:#0c25344d}.df-combat .combat-reaction h3{color:#bddde7}.df-combat .combat-timing{margin:7px 0;color:#e6cb92;font:13px/1.5 system-ui,sans-serif}.df-combat .combat-draft{margin-top:23px}.df-combat .df-ui-field{display:grid;gap:7px}.df-combat .df-ui-field label{display:grid;gap:8px;font:12px/1.6 system-ui,sans-serif;color:#b7c6d1}.df-combat input{width:100%;min-height:48px;color:#f5eee0;background:#07111b;border:1px solid #8b9eaf66;border-radius:3px;font:14px/1.5 system-ui,sans-serif;padding:12px 14px}.df-combat input[aria-invalid=true]{border-color:#e0a19a}.df-combat .df-ui-feedback,.df-combat .combat-feedback{font:13px/1.6 system-ui,sans-serif;margin:8px 0 0;color:#bfdbe8}.df-combat .combat-feedback[data-state=refused]{color:#f0beb4}.df-combat .combat-roll{position:relative;padding:0 0 19px;margin:0 0 20px;border-bottom:1px solid #96a6b82b}.df-combat .combat-roll:last-child{border-bottom:0;margin:0;padding-bottom:0}.df-combat .combat-roll h3{font:13px/1.5 system-ui,sans-serif;color:#ccd8df;letter-spacing:.3px}.df-combat .combat-roll-value{font:36px/1.3 Georgia,serif;color:#efce90;margin:9px 0}.df-combat .combat-roll-explanation{font:13px/1.75 system-ui,sans-serif;color:#d0d5d5;margin:5px 0}.df-combat .combat-roll-source{font:10px/1.6 system-ui,sans-serif;color:#93a6b5;margin:8px 0 0}.df-combat .combat-connection{text-align:center;color:#93a3b4;font:11px/1.7 system-ui,sans-serif;padding:0 4vw 24px}.df-combat .combat-fixture-tools{width:min(1480px,92vw);margin:0 auto 30px;border-top:1px solid #ad925d55;padding-top:20px}.df-combat .combat-fixture-tools summary{min-height:44px;color:#dfb974;cursor:pointer}.df-combat .combat-fixture-tools nav{display:flex;flex-wrap:wrap;gap:8px}.df-combat .combat-fixture-tools button{width:auto}.df-combat .combat-fixture-status{font:12px/1.6 system-ui,sans-serif;color:#b6bec6}
@media(min-width:1600px){.df-combat .combat-stage{min-height:610px}}@media(max-width:1000px){.df-combat .combat-stage{grid-template-columns:1fr 280px;gap:28px;padding-top:70px}.df-combat .combat-lower{grid-template-columns:1fr 1fr}.df-combat .combat-offers{grid-template-columns:1fr}.df-combat .combat-action-rail,.df-combat .combat-roll-panel{padding:23px}.df-combat h1{font-size:60px}}
@media(max-width:700px){.df-combat .combat-topbar{padding:18px 5vw;gap:14px;flex-wrap:wrap}.df-combat .combat-location{order:3;flex-basis:100%;font-size:10px}.df-combat .combat-brand{font-size:26px;flex:1}.df-combat .combat-notice{font-size:9px;max-width:150px}.df-combat .combat-stage{display:flex;flex-direction:column;align-items:stretch;gap:30px;width:90vw;padding:115px 0 25px;min-height:0}.df-combat .combat-story{padding:0}.df-combat h1{font-size:48px;letter-spacing:-1px}.df-combat .combat-narration{font-size:17px}.df-combat .combat-art{height:660px;object-position:45% center}.df-combat:before{background:linear-gradient(180deg,#03080f80,transparent 18%,#070d14 610px)}.df-combat .combat-lower{width:90vw;grid-template-columns:1fr;gap:20px}.df-combat .combat-action-rail,.df-combat .combat-roll-panel{padding:23px 20px}.df-combat .combat-initiative{padding:20px}.df-combat .combat-fixture-tools{width:90vw}.df-combat .combat-fixture-tools nav{display:grid;grid-template-columns:1fr 1fr}.df-combat .combat-fixture-tools button{width:100%;font-size:12px}}
@media(prefers-reduced-motion:reduce){.df-combat *,.df-combat *:before,.df-combat *:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
"#;
